# ============================================================
# KNOWN CANONICAL NAMES — for fuzzy matching
# ============================================================
_KNOWN_CANONICAL = frozenset(TEAM_ALIASES.values())


# ============================================================
# _strip_accents — remove diacritics
# ============================================================
def _strip_accents(text: str) -> str:
    """Remove accents/diacritics from text, handling special chars."""
    special = {
        'ł': 'l', 'Ł': 'l',
        'ø': 'o', 'Ø': 'o',
        'ð': 'd', 'Ð': 'd',
        'þ': 'th', 'Þ': 'th',
        'ß': 'ss',
        'đ': 'd', 'Đ': 'd',
        'ı': 'i', 'I': 'i',
    }
    for src, dst in special.items():
        text = text.replace(src, dst)
    nfkd = unicodedata.normalize('NFKD', text)
    return ''.join(c for c in nfkd if not unicodedata.combining(c))


# ============================================================
# _auto_normalize — strip safe suffixes/prefixes
# ============================================================
_CLUB_SUFFIXES = frozenset([
    'fc', 'sc', 'cf', 'afc', 'utd', 'ac', 'ss', 'sd',
    'fk', 'nk', 'bk', 'if', 'il', 'ek',
])
_PREFIX_TOKENS = frozenset([
    'asu', 'csa', 'clb', 'cd', 'ca', 'ce', 'cs', 'rcd', 'rcc', 'gnk',
])
_PREPOSITIONS = frozenset([
    'de', 'del', 'da', 'do', 'dos', 'las', 'los', 'el', 'la',
])


def _auto_normalize(key: str) -> str:
    """Strip safe suffixes/prefixes, return result."""
    tokens = key.split('_')
    if not tokens:
        return key
    
    while len(tokens) > 1 and tokens[-1] in _CLUB_SUFFIXES:
        tokens.pop()
    
    while len(tokens) > 1 and tokens[0] in _PREFIX_TOKENS:
        tokens.pop(0)
    
    if len(tokens) > 2:
        tokens = [t for i, t in enumerate(tokens) 
                  if t not in _PREPOSITIONS or i == 0 or i == len(tokens)-1]
    
    return '_'.join(tokens)


# ============================================================
# _fuzzy_match — find closest known canonical
# ============================================================
def _fuzzy_match(key: str, threshold: float = 0.92) -> str:
    """Find closest match in known canonicals using SequenceMatcher."""
    best_match = None
    best_ratio = 0.0
    for canonical in _KNOWN_CANONICAL:
        ratio = SequenceMatcher(None, key, canonical).ratio()
        if ratio > best_ratio:
            best_ratio = ratio
            best_match = canonical
    if best_ratio >= threshold:
        return best_match
    return key


# ============================================================
# clean_team_name — normalization pipeline (6 steps)
# ============================================================
def clean_team_name(name: str) -> str:
    """Normalize team name to canonical form.
    
    Pipeline:
    1. Exact alias lookup (with accents)
    2. Accent-stripped + spaces→underscores alias lookup
    3. Hyphen → underscore + alias lookup
    4. Auto-normalize (strip safe suffixes)
    5. Fuzzy match (>=0.92)
    6. Fallback: return normalized key with underscores
    """
    if not name:
        return ""
    
    key = name.strip().lower()
    if not key:
        return ""
    
    # Step 1: Exact alias lookup
    if key in TEAM_ALIASES:
        return TEAM_ALIASES[key]
    
    # Also try spaces → underscores for exact lookup
    underscore_key = key.replace(' ', '_')
    if underscore_key != key and underscore_key in TEAM_ALIASES:
        return TEAM_ALIASES[underscore_key]
    
    # Step 2: Accent stripping
    stripped = _strip_accents(key)
    stripped_us = stripped.replace(' ', '_')
    if stripped_us != key:
        if stripped in TEAM_ALIASES:
            return TEAM_ALIASES[stripped]
        if stripped_us in TEAM_ALIASES:
            return TEAM_ALIASES[stripped_us]
    
    # Step 3: Hyphen → underscore
    hyphen_key = stripped_us.replace('-', '_')
    if hyphen_key != stripped_us and hyphen_key in TEAM_ALIASES:
        return TEAM_ALIASES[hyphen_key]
    
    # Step 4: Auto-normalize (only if result is in known canonicals)
    normalized = _auto_normalize(hyphen_key)
    if normalized != hyphen_key and normalized in TEAM_ALIASES:
        return TEAM_ALIASES[normalized]
    
    # Step 5: Fuzzy match
    fuzzy = _fuzzy_match(hyphen_key)
    if fuzzy != hyphen_key:
        return fuzzy
    
    # Step 6: Fallback — return with underscores
    return hyphen_key


def build_canonical_id(home_team: str, away_team: str, date_utc: str) -> str:
    """
    Build canonical match ID from team names and date.
    Format: {home_clean}__{away_clean}__{YYYYMMDD}
    """
    home_clean = clean_team_name(home_team)
    away_clean = clean_team_name(away_team)
    
    date_str = ""
    if date_utc:
        date_part = date_utc.strip()[:10]
        if len(date_part) >= 10 and date_part[4] == "-" and date_part[7] == "-":
            date_str = date_part[:4] + date_part[5:7] + date_part[8:10]
    
    if not home_clean or not away_clean:
        return ""
    if not date_str:
        return ""
    
    return f"{home_clean}__{away_clean}__{date_str}"


